parameters.func:
=const pkt = $json[0];
return {
  json: {
    packet_id: pkt.packet_id,
    active_objective: pkt.active_objective,
    current_task_id: pkt.current_task_id,
    next_command: pkt.next_command,
    branch: pkt.branch,
    drift_status: pkt.drift_status
  }
};

parameters.body:
=JSON.stringify({
  to: "all",
  subject: "n8n-relay:resumed",
  body: `RESUMED from pkt-${$json.packet_id}, item: ${$json.current_task_id}, drift: ${$json.drift_status}`
})

parameters.func:
=const WS = process.env.META_ROOT + '/n8n/_workspace';
const fs = require('fs');
const sentinels = ['DONE', 'NEEDS-HUMAN', 'STOP'];
for (const s of sentinels) {
  if (fs.existsSync(WS + '/' + s)) {
    console.log(`Stopping: sentinel ${s} present`);
    return { json: { stop: true, reason: s } };
  }
}
return { json: { stop: false } };

parameters.body:
=JSON.stringify({
  prompt: `/n8n-loop resume from _workspace/HANDOFF.md (branch ${$json.branch}). Packet: ${$json.packet_id}. Objective: ${$json.active_objective}. Item: ${$json.current_task_id}. Verify baseline, reset counter, continue at next item.`,
  model: process.env.N8N_LOOP_MODEL || 'opus',
  stream: true
})
